// CreditServiceClient is the client API for CreditService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// CreditService submits and tracks FFC2 credit/installment applications
// (apply-lead-factoring) and their refunds (factoring-refund). Amounts are
// tiyn everywhere in this API; cg-payments converts to tenge at the FFC
// adapter boundary. Application/refund outcomes arrive asynchronously via
// the FFC hook and are published as `credit.*` payment events.
type CreditServiceClient interface {
	// CreateCreditApplication accepts an authoritative credit intent only from
	// the service that owns entity_type (owner-service mapping, like
	// PaymentService.CreateTransaction). It creates the local application row
	// first, then submits the FFC lead and binds uuid + redirect_url.
	CreateCreditApplication(ctx context.Context, in *CreateCreditApplicationRequest, opts ...grpc.CallOption) (*CreateCreditApplicationResponse, error)
	// GetCreditApplication resolves by FFC uuid or by (entity_type, entity_id).
	GetCreditApplication(ctx context.Context, in *GetCreditApplicationRequest, opts ...grpc.CallOption) (*GetCreditApplicationResponse, error)
	// RefundCreditApplication initiates a full or partial refund for an ISSUED
	// application. The result is asynchronous (FFC hook, covlir_status).
	RefundCreditApplication(ctx context.Context, in *RefundCreditApplicationRequest, opts ...grpc.CallOption) (*RefundCreditApplicationResponse, error)
	// ListCessionLoans returns the loans issued on issue_date under our partner
	// id together with the exact total the bank will validate. Use it to render
	// the assignment agreement document.
	ListCessionLoans(ctx context.Context, in *ListCessionLoansRequest, opts ...grpc.CallOption) (*ListCessionLoansResponse, error)
	// SubmitCessionAgreement signs the supplied PDF with the partner EDS key and
	// posts it to the conveyor. The final outcome arrives asynchronously on the
	// partner-wide cession hook.
	SubmitCessionAgreement(ctx context.Context, in *SubmitCessionAgreementRequest, opts ...grpc.CallOption) (*SubmitCessionAgreementResponse, error)
	GetCessionAgreement(ctx context.Context, in *GetCessionAgreementRequest, opts ...grpc.CallOption) (*GetCessionAgreementResponse, error)
	// ListPartnerProducts returns the bank products available to us with their
	// amount ranges and allowed periods, so the storefront can offer only terms
	// the conveyor will accept.
	ListPartnerProducts(ctx context.Context, in *ListPartnerProductsRequest, opts ...grpc.CallOption) (*ListPartnerProductsResponse, error)
	// RefreshCreditApplicationStatus pulls the conveyor's current status for a
	// goods-loan application. Hooks remain the primary signal; this is the
	// recovery path when a hook is lost.
	RefreshCreditApplicationStatus(ctx context.Context, in *RefreshCreditApplicationStatusRequest, opts ...grpc.CallOption) (*RefreshCreditApplicationStatusResponse, error)
}

